package dev.kindred.core.progression;

import dev.kindred.core.TaskPreferences;

import java.util.Map;
import java.util.Objects;

/**
 * In plain terms: one suggested job from the progression map: which step it serves, the skill to use and how
 * important it is.
 *
 * Technical: Recommended candidate skill proposal generated by the ProgressionPolicy.
 */
public record ProgressionRecommendation(
        MilestoneId milestoneId,
        String skill,
        Map<String, String> arguments,
        TaskPreferences.Priority priority,
        double need,
        TaskPreferences.Affinities affinities,
        String rationale
) {
    public ProgressionRecommendation {
        Objects.requireNonNull(milestoneId, "milestoneId");
        Objects.requireNonNull(skill, "skill");
        arguments = Map.copyOf(Objects.requireNonNull(arguments, "arguments"));
        Objects.requireNonNull(priority, "priority");
        Objects.requireNonNull(affinities, "affinities");
        Objects.requireNonNull(rationale, "rationale");
    }
}
